const r = await tools.exec_command({
  cmd: "cp src/mcp-apps/_shared/host.test.tsx /tmp/host.test.tsx.review-orig
cat > /tmp/host-review-case.txt <<'EOF'

	it("restores state when standard and compatibility deliveries overlap", async () => {
		type RestoreResult = {
			isError: false;
			structuredContent: {
				found: true;
				tool_name: string;
				data: { title: string };
				view_state: { "details.open": true };
			};
		};
		const compatParent: CompatParent = Object.assign(new EventTarget(), {
			location: { origin: "https://chatgpt.com" },
		});
		Object.defineProperty(window, "parent", {
			configurable: true,
			value: compatParent,
		});
		let resolveRestore: ((result: RestoreResult) => void) | undefined;
		const restore = new Promise<RestoreResult>((resolve) => {
			resolveRestore = resolve;
		});
		bridge.callServerTool.mockImplementation(async ({ name }) => {
			if (name === "restore_lobu_app_result") return restore;
			if (name === "save_lobu_app_state") {
				return { isError: false, structuredContent: { saved: true } };
			}
			return { isError: false };
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, viewState } = useMcpApp<{ title: string }>();
			return (
				<>
					<span>{data?.title}</span>
					<span data-testid="state">
						{String(viewState["details.open"])}
					</span>
				</>
			);
		}
		render(
			<Provider devMock={{ title: "Development result" }}>
				<Probe />
			</Provider>,
		);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({
					structuredContent: { title: "Same live result" },
					_meta: {
						"lobu/mcp-app-snapshot-capability": "duplicate-token",
					},
				});
			}
		});
		await waitFor(() =>
			expect(bridge.callServerTool).toHaveBeenCalledWith({
				name: "restore_lobu_app_result",
				arguments: { snapshot_capability: "duplicate-token" },
			}),
		);
		act(() => {
			window.dispatchEvent(
				new CustomEvent("openai:set_globals", {
					detail: {
						globals: {
							toolOutput: { title: "Same live result" },
							toolResponseMetadata: {
								mcp_tool_result: {
									_meta: {
										"lobu/mcp-app-snapshot-capability":
											"duplicate-token",
									},
								},
							},
						},
					},
				}),
			);
		});
		await act(async () => {
			if (!resolveRestore) throw new Error("restore was not requested");
			resolveRestore({
				isError: false,
				structuredContent: {
					found: true,
					tool_name: "query_sdk",
					data: { title: "Same live result" },
					view_state: { "details.open": true },
				},
			});
			await restore;
		});
		await waitFor(() =>
			expect(screen.getByTestId("state")).toHaveTextContent("true"),
		);
	});
